package com.sports.payment_service.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat; @Service public class WebhookSignatureService { @Value("${paystack.secret-key:}") String key; public boolean isValid(String body,String sig){ if(key==null||key.isBlank()||sig==null||sig.isBlank())return false; try{Mac m=Mac.getInstance("HmacSHA512");m.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"HmacSHA512"));return MessageDigest.isEqual(m.doFinal(body.getBytes(StandardCharsets.UTF_8)),HexFormat.of().parseHex(sig));}catch(Exception e){return false;}} }